use rbx_dom_weak::{WeakDom,InstanceBuilder,types::*};
use serde_json::Value;
use std::collections::BTreeMap;
fn number(value:&Value,key:&str)->anyhow::Result<f32>{let n=value[key].as_f64().ok_or_else(||anyhow::anyhow!("Missing numeric {key}"))?;anyhow::ensure!(n.is_finite()&&n.abs()<=1e9,"Invalid numeric {key}");Ok(n as f32)}
fn color(value:&Value)->anyhow::Result<Color3>{if let Some(hex)=value["hex"].as_str(){anyhow::ensure!(hex.len()==7&&hex.starts_with('#')&&hex.as_bytes()[1..].iter().all(u8::is_ascii_hexdigit),"Invalid hex color.");let bytes=(1..7).step_by(2).map(|i|u8::from_str_radix(&hex[i..i+2],16)).collect::<Result<Vec<_>,_>>()?;Ok(Color3::new(bytes[0] as f32/255.,bytes[1] as f32/255.,bytes[2] as f32/255.))}else{Ok(Color3::new(number(value,"r")?,number(value,"g")?,number(value,"b")?))}}
fn typed(value:&Value,refs:&BTreeMap<String,Ref>)->anyhow::Result<Variant>{
    if let Some(v)=value.as_bool(){return Ok(v.into());}if let Some(v)=value.as_f64(){anyhow::ensure!(v.is_finite(),"Nonfinite property.");return Ok(Variant::Float64(v));}if let Some(v)=value.as_str(){return Ok(v.to_owned().into());}
    Ok(match value["type"].as_str().unwrap_or(""){
        "Color3"=>color(value)?.into(),"Vector3"=>Vector3::new(number(value,"x")?,number(value,"y")?,number(value,"z")?).into(),"Vector2"=>Vector2::new(number(value,"x")?,number(value,"y")?).into(),
        "UDim"=>UDim::new(number(value,"scale")?,number(value,"offset")? as i32).into(),
        "UDim2"=>{let n=|short:&str,long:&str|{let v=value[short].as_f64().or_else(||value[long].as_f64()).unwrap_or(0.);anyhow::ensure!(v.is_finite()&&v.abs()<=1e9,"Invalid UDim2");Ok::<f32,anyhow::Error>(v as f32)};UDim2::new(UDim::new(n("xs","xScale")?,n("xo","xOffset")? as i32),UDim::new(n("ys","yScale")?,n("yo","yOffset")? as i32)).into()},
        "Enum"=>{let text=value["value"].as_str().unwrap_or("").trim_start_matches("Enum.");let (kind,item)=text.split_once('.').ok_or_else(||anyhow::anyhow!("Invalid enum."))?;let db=rbx_reflection_database::get()?;let numeric=db.enums.get(kind).and_then(|e|e.items.get(item)).ok_or_else(||anyhow::anyhow!("Unknown enum {text}; no property was dropped."))?;Enum::from_u32(*numeric).into()},
        "Ref"=>Variant::Ref(*refs.get(value["id"].as_str().unwrap_or("")).ok_or_else(||anyhow::anyhow!("Missing reference."))?),"Nil"=>Variant::Ref(Ref::none()),
        "Rect"=>Rect::new(Vector2::new(number(value,"minX")?,number(value,"minY")?),Vector2::new(number(value,"maxX")?,number(value,"maxY")?)).into(),
        "NumberRange"=>NumberRange::new(number(value,"min")?,number(value,"max")?).into(),
        "BrickColor"=>BrickColor::from_name(value["name"].as_str().unwrap_or("")).ok_or_else(||anyhow::anyhow!("Unknown BrickColor."))?.into(),
        "NumberSequence"=>NumberSequence{keypoints:value["keypoints"].as_array().ok_or_else(||anyhow::anyhow!("Missing keypoints."))?.iter().map(|p|Ok(NumberSequenceKeypoint::new(number(p,"time")?,number(p,"value")?,number(p,"envelope")?))).collect::<anyhow::Result<_>>()?}.into(),
        "ColorSequence"=>ColorSequence{keypoints:value["keypoints"].as_array().ok_or_else(||anyhow::anyhow!("Missing keypoints."))?.iter().map(|p|Ok(ColorSequenceKeypoint::new(number(p,"time")?,color(&p["color"])?))).collect::<anyhow::Result<_>>()?}.into(),
        "CFrame"=>{let rx=number(value,"rx")?.to_radians();let ry=number(value,"ry")?.to_radians();let rz=number(value,"rz")?.to_radians();let (sx,cx)=rx.sin_cos();let (sy,cy)=ry.sin_cos();let(sz,cz)=rz.sin_cos();let matrix=Matrix3::new(Vector3::new(cy*cz+sy*sx*sz,-cy*sz+sy*sx*cz,sy*cx),Vector3::new(cx*sz,cx*cz,-sx),Vector3::new(-sy*cz+cy*sx*sz,sy*sz+cy*sx*cz,cy*cx));CFrame::new(Vector3::new(number(value,"x")?,number(value,"y")?,number(value,"z")?),matrix).into()},
        kind=>anyhow::bail!("Unsupported export type {kind}; no property was dropped.")
    })
}
pub fn export(blueprint:&Value,animations:bool)->anyhow::Result<String>{
    let nodes=blueprint["nodes"].as_array().ok_or_else(||anyhow::anyhow!("Missing nodes."))?;anyhow::ensure!(nodes.len()<=800,"Export too large.");let mut dom=WeakDom::new(InstanceBuilder::new("DataModel"));let container=dom.root_ref();let mut refs=BTreeMap::new();
    for node in nodes {let id=node["id"].as_str().unwrap_or("");let class=node["class"].as_str().unwrap_or("");anyhow::ensure!(!matches!(class,"Script"|"LocalScript"|"ModuleScript")&&!class.is_empty(),"Blueprints cannot supply executable scripts.");let name=node["name"].as_str().filter(|s|!s.is_empty()).unwrap_or(id);let reference=dom.insert(container,InstanceBuilder::new(class).with_name(name));anyhow::ensure!(refs.insert(id.to_owned(),reference).is_none(),"Duplicate ID.");}
    for node in nodes {let reference=refs[node["id"].as_str().unwrap()];let mut props=Vec::new();for (name,value) in node["properties"].as_object().into_iter().flatten(){anyhow::ensure!(!matches!(name.as_str(),"Source"|"Parent"|"Name"|"LinkedSource"),"Reserved export property.");props.push((name.clone(),typed(value,&refs)?));}
        let mut attributes=Attributes::new();for (name,value) in node["attributes"].as_object().into_iter().flatten(){attributes.insert(name.clone(),typed(value,&refs)?);}attributes.insert("elioNodeId".into(),node["id"].as_str().unwrap().to_owned().into());attributes.insert("elioBuildId".into(),blueprint["build_id"].as_str().unwrap_or("").to_owned().into());props.push(("Attributes".into(),attributes.into()));for(name,value)in props{dom.get_by_ref_mut(reference).unwrap().properties.insert(name.into(),value);}
        let parent=node["parent"].as_str().unwrap_or("");if !parent.is_empty(){dom.transfer_within(reference,*refs.get(parent).ok_or_else(||anyhow::anyhow!("Missing parent."))?);}
    }
    let root=*refs.get(blueprint["root_id"].as_str().unwrap_or("")).ok_or_else(||anyhow::anyhow!("Missing root."))?;
    if animations&&blueprint["mode"]=="ui"{dom.insert(root,InstanceBuilder::new("LocalScript").with_name("elioPresentation").with_property("Source",include_str!(concat!(env!("ELIO_EXTENSION_ROOT"),"/core/creator-animations.luau"))));}
    let mut bytes=Vec::new();rbx_xml::to_writer(&mut bytes,&dom,&[root],rbx_xml::EncodeOptions::new().property_behavior(rbx_xml::EncodePropertyBehavior::ErrorOnUnknown))?;let text=String::from_utf8(bytes)?;
    // Parse what we exported; malformed/unserializable output cannot be downloaded as success.
    let _=rbx_xml::from_reader(text.as_bytes(),rbx_xml::DecodeOptions::new().property_behavior(rbx_xml::DecodePropertyBehavior::ErrorOnUnknown))?;Ok(text)
}
#[cfg(test)]mod tests{use super::*;use serde_json::json;
#[test]fn exports_materials_transforms_refs_attributes_and_animation(){let blueprint=json!({"build_id":"export","root_id":"root","mode":"model","nodes":[{"id":"root","class":"Model","name":"A<& model"},{"id":"part","class":"Part","parent":"root","properties":{"Size":{"type":"Vector3","x":2,"y":3,"z":4},"Material":{"type":"Enum","value":"Material.WoodPlanks"},"CFrame":{"type":"CFrame","x":1,"y":2,"z":3,"rx":30,"ry":45,"rz":60}},"attributes":{"Custom":"value"}},{"id":"weld","class":"WeldConstraint","parent":"root","properties":{"Part0":{"type":"Ref","id":"part"},"Part1":{"type":"Ref","id":"part"}}}]});let xml=export(&blueprint,false).unwrap();let dom=rbx_xml::from_reader(xml.as_bytes(),Default::default()).unwrap();assert_eq!(dom.root().children().len(),1);let root=dom.get_by_ref(dom.root().children()[0]).unwrap();assert_eq!(root.name,"A<& model");assert_eq!(root.children().len(),2);let part=dom.get_by_ref(root.children()[0]).unwrap();assert_eq!(part.properties.get(&"Material".into()),Some(&Variant::Enum(Enum::from_u32(528))));assert!(part.properties.contains_key(&"Attributes".into()));let ui=json!({"build_id":"ui","root_id":"root","mode":"ui","nodes":[{"id":"root","class":"ScreenGui"},{"id":"button","parent":"root","class":"TextButton","properties":{"Text":"Buy","TextSize":18,"Size":{"type":"UDim2","xs":0,"xo":120,"ys":0,"yo":44},"Font":{"type":"Enum","value":"Font.GothamBold"}}}]});assert!(export(&ui,true).unwrap().contains("elioPresentation"));let mut bad=blueprint.clone();bad["nodes"][1]["properties"]["Source"]="bad".into();assert!(export(&bad,false).is_err());}
}
